22	create function public.audit_import_row_decision() returns trigger language plpgsql security definer set search_path='' as $$
23	begin
24	  if old.status in ('review','new') and new.status in ('accepted','rejected') and not ('excluded_by_review'=any(new.review_reasons)) then
25	    insert into public.import_row_decisions(workspace_id,source_id,action,source_record,transaction_record,balance_records,actor_id)
26	    values(new.workspace_id,new.id,new.status,to_jsonb(new),
27	      (select to_jsonb(t) from public.transactions t join public.transaction_sources l on l.transaction_id=t.id where l.source_transaction_id=new.id),
28	      (select coalesce(jsonb_agg(to_jsonb(b) order by b.id),'[]'::jsonb) from public.balance_snapshots b where b.source_transaction_id=new.id),auth.uid());
29	  end if;
30	  return new;
31	end;
32	$$;
33	create trigger source_transaction_review_history after update of status on public.source_transactions for each row execute function public.audit_import_row_decision();
34	revoke all on function public.audit_import_row_decision() from public,anon,authenticated;
