60	create function public.undo_transaction_correction(
61	  p_event_id uuid,
62	  p_expected_version integer
63	) returns public.transactions
64	language plpgsql security definer set search_path = '' as $$
65	declare
66	  event_row public.correction_events%rowtype;
67	  old_row public.transactions%rowtype;
68	  new_row public.transactions%rowtype;
69	begin
70	  if auth.uid() is null then
71	    raise exception 'Authentication required' using errcode = '28000';
72	  end if;
73	
74	  select * into event_row from public.correction_events
75	  where id = p_event_id and public.owns_workspace(workspace_id);
76	  if not found then
77	    raise exception 'Correction not found' using errcode = 'P0002';
78	  end if;
79	
80	  select * into old_row from public.transactions
81	  where id = event_row.transaction_id and workspace_id = event_row.workspace_id
82	  for update;
83	  if old_row.version is distinct from p_expected_version then
84	    raise exception 'Transaction changed; refresh and retry' using errcode = '40001';
85	  end if;
86	
87	  select * into event_row from public.correction_events
88	  where id = p_event_id and not undone and not exists (
89	    select 1 from public.correction_events newer
90	    where newer.transaction_id = correction_events.transaction_id
91	      and not newer.undone
92	      and (newer.after->>'version')::integer > (correction_events.after->>'version')::integer
93	  );
94	  if not found then
95	    raise exception 'Only the latest correction can be undone' using errcode = '40001';
96	  end if;
97	  if old_row.category_id is distinct from (event_row.after->>'category_id')::uuid
98	     or old_row.note is distinct from event_row.after->>'note' then
99	    raise exception 'Transaction changed; refresh and retry' using errcode = '40001';
100	  end if;
101	
102	  update public.transactions
103	  set category_id = (event_row.before->>'category_id')::uuid,
104	      note = event_row.before->>'note', version = version + 1
105	  where id = old_row.id
106	  returning * into new_row;
107	  update public.correction_events set undone = true where id = p_event_id;
108	  return new_row;
109	end;
110	$$;
111	
